//! Native QWER and D/F icons/overlays, using original widgets and current core state.
use bevy::{prelude::*,image::CompressedImageFormats,render::renderer::RenderDevice,ui_render::ui_material::MaterialNode,window::PrimaryWindow};
use crate::{native_zip_provider::StartupHud,native_hud_panels::Panel,native_hud_element_storage::ElementStorage,native_hud_icon_material::IconMaterial};
struct Icon {image:Handle<Image>,asset:String}
#[derive(Resource,Default)] struct Live {panels:Vec<Panel>,summoners:std::collections::BTreeMap<String,Icon>,icons:std::collections::BTreeMap<(String,u8),Icon>,entities:Vec<Entity>,materials:Vec<Handle<IconMaterial>>,signature:Option<String>,error:Option<String>}
pub struct Plugin;
impl bevy::app::Plugin for Plugin {fn build(&self,app:&mut App) {app.init_resource::<Live>().add_systems(Startup,setup).add_systems(Update,update.after(crate::receive).before(crate::render_probe::capture));}}
fn source(hud:&StartupHud)->Result<Vec<Panel>,String> {
 let mut result=Vec::new();for slot in 0..crate::native_hud_summoners::SLOT_COUNT {let path=crate::native_hud_summoners::layout(slot);for layout in &hud.shadow_isles_layouts {if !layout.request.ends_with(&path) {continue;}for record in &layout.structure.accepted {
  let s=&record.element.storage;if s.kind()!=1 {continue;}let name=std::str::from_utf8(s.bytes()[..32].split(|b|*b==0).next().unwrap()).map_err(|_|"spell widget name")?;
  let accepted=if slot<4 {name==format!("Spell{slot}") || name==format!("SpellOverlay{slot}")}
  else {let local=slot-4;name==format!("SummonerSpell{local}") || name==format!("SummonerSpellOverlay{local}") || name==format!("SummonerSpellHotKeyBG{local}")};if !accepted {continue;}if s.flags()&1==0 || s.bytes()[0x204..0x214]!=s.bytes()[0x214..0x224] {return Err("unqualified spell source state".into());}
  let mut storage=ElementStorage::new(1).unwrap();storage.write_bytes(0,s.bytes());result.push(Panel {name:name.into(),path:layout.request.clone(),storage});
 }}}if result.len()!=14 {return Err("fourteen native QWER/D/F icon widgets missing or duplicated".into());}Ok(result)
}
pub(crate) fn state(available:bool,cooldown:f32,rank:u8,allowed:bool,resource_state:u32)->u32 {if !available {1}else if cooldown>0.0 {4}else if rank==0 {2}else if !allowed {3}else {resource_state}}
fn color(state:u32,override_:bool,hover:bool)->u32 {
 static CONTRACT:std::sync::OnceLock<serde_json::Value>=std::sync::OnceLock::new();let c=CONTRACT.get_or_init(||serde_json::from_str(include_str!("../../../data/4.20/native_hud_spell_states_contract.json")).unwrap());
 let key=if hover && (state==0 || override_) {"RollOverColor"}else if !override_ && matches!(state,2|3) {"DisabledColor"}else if !override_ && state==4 {"CooldownColor"}else if !override_ && state==5 {"OutOfManaColor"}else {"EnabledColor"};c["palette"][key].as_u64().unwrap() as u32
}
pub(crate) fn player_states(p:&openleague_core::Champion,tick:u64)->Result<[u32;4],String> {
 static SPELLS:std::sync::OnceLock<serde_json::Value>=std::sync::OnceLock::new();let spells=SPELLS.get_or_init(||serde_json::from_str(include_str!("../../../data/4.20/native_spells_420.json")).unwrap());
 if !p.health.is_finite() || !p.mana.is_finite() {return Err("invalid authoritative spell resource".into());}
 let allowed=p.health>0.0 && !p.stuns.iter().any(|s|s.expires_at>tick);let mut result=[2;4];
 for slot in 0..4 {let rank=p.ranks[slot];if rank>5 || (slot==3 && rank>3) {return Err("special rank scheme requires native HUD contract".into());}
  let cooldown=p.cooldowns[slot].saturating_sub(tick) as f32/openleague_core::TICK_RATE as f32;
  let resource_state=if rank==0 || cooldown>0.0 || !allowed {0}else {
   let record=spells.as_array().unwrap().iter().find(|s|s["champion"].as_str().unwrap().eq_ignore_ascii_case(&p.champion) && s["slot"]==slot).ok_or("native spell cost reference missing")?;let cost=&record["values"][format!("ManaCost{rank}")];let cost=cost.as_f64().map(|n|n as f32).or_else(||cost.as_str().and_then(|s|s.parse::<f32>().ok())).ok_or("native spell cost unknown")?;
   if !cost.is_finite() || cost<0.0 {return Err("invalid native spell cost".into());}if p.mana<cost {5}else {0}
  };result[slot]=state(true,cooldown,rank,allowed,resource_state);
 }Ok(result)
}
fn setup(hud:Res<StartupHud>,device:Res<RenderDevice>,mut images:ResMut<Assets<Image>>,mut live:ResMut<Live>) {
 match source(&hud) {Ok(p)=>live.panels=p,Err(e)=>{eprintln!("Native QWER HUD unavailable: {e}");return;}}
 let root=std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");let manifest:serde_json::Value=serde_json::from_str(include_str!("../../../data/4.20/native_spell_icons.json")).unwrap();
 for entry in manifest["entries"].as_array().unwrap().iter().filter(|e|e["field"]=="InventoryIcon") {let champion=entry["champion"].as_str().unwrap();let slot=entry["slot"].as_u64().unwrap() as u8;let asset=entry["asset"].as_str().unwrap();match std::fs::read(root.join("assets").join(asset)).map_err(|e|e.to_string()).and_then(|b|crate::native_hud_atlases::decode(&b,CompressedImageFormats::from_features(device.features())).map_err(|e|e.to_string())) {Ok(image)=>{live.icons.insert((champion.into(),slot),Icon {image:images.add(image),asset:asset.into()});},Err(e)=>eprintln!("Native QWER icon unavailable {champion}/{slot}: {e}")}}
 for entry in crate::native_hud_summoners::catalog()["entries"].as_array().unwrap() {let name=entry["native_name"].as_str().unwrap();let asset=entry["asset"].as_str().unwrap();match std::fs::read(root.join("assets").join(asset)).map_err(|e|e.to_string()).and_then(|b|crate::native_hud_atlases::decode(&b,CompressedImageFormats::from_features(device.features())).map_err(|e|e.to_string())) {Ok(image)=>{live.summoners.insert(name.into(),Icon {image:images.add(image),asset:asset.into()});},Err(e)=>eprintln!("Native summoner icon unavailable {name}: {e}")}}
 eprintln!("Native HUD icons QWER={} summoners={} primary_variants_only=true",live.icons.len(),live.summoners.len());
}
fn clear(live:&mut Live,commands:&mut Commands,materials:&mut Assets<IconMaterial>) {for e in live.entities.drain(..) {commands.entity(e).despawn();}for m in live.materials.drain(..) {materials.remove(m.id());}live.signature=None;}
fn update(mut commands:Commands,game:Res<crate::Match>,connection:Res<crate::Connection>,window:Query<&Window,With<PrimaryWindow>>,viewport:Res<crate::native_hud_viewport::Viewport>,atlases:Res<crate::native_hud_atlases::Atlases>,mut materials:ResMut<Assets<IconMaterial>>,mut live:ResMut<Live>) {
 if live.panels.len()!=14 {return;}let Some(snapshot)=&game.snapshot else {clear(&mut live,&mut commands,&mut materials);return;};let Some(player)=snapshot.players.iter().find(|p|Some(p.id)==connection.id) else {clear(&mut live,&mut commands,&mut materials);return;};
 let states=match crate::native_hud_summoners::all_states(player,snapshot.tick) {Ok(v)=>v,Err(e)=>{clear(&mut live,&mut commands,&mut materials);if live.error.as_ref()!=Some(&e) {eprintln!("Native QWER HUD state unavailable: {e}");live.error=Some(e);}return;}};
 let Ok(window)=window.single() else{return;};let dimensions=[window.physical_width(),window.physical_height()];let dpi=window.scale_factor();let signature=signature(snapshot.session,connection.id,player,&states,dimensions,dpi,viewport.scalar);if live.signature.as_ref()==Some(&signature) {return;}
 let result=(||->Result<Vec<(Node,IconMaterial,serde_json::Value,i32)>,String> {let mut payloads=Vec::new();for panel in &live.panels {
  let slot=crate::native_hud_summoners::panel_slot(&panel.name);let overlay=panel.name.contains("Overlay");let background=panel.name.contains("HotKeyBG");
  let icon=if slot<4 {live.icons.get(&(player.champion.clone(),slot as u8))}else {player.summoners.spells[slot-4].and_then(|spell|live.summoners.get(crate::native_hud_summoners::native_name(spell)))};
  if !background && icon.is_none() {continue;}let (texture,asset)=if overlay || background {(atlases.entries.iter().find(|a|a.normalized.ends_with("/HUDAtlas.dds")).ok_or("native spell overlay atlas missing")?.image.clone(),"HUDAtlas")}else {let icon=icon.unwrap();(icon.image.clone(),icon.asset.as_str())};
  let mut storage=ElementStorage::new(1).unwrap();storage.write_bytes(0,panel.storage.bytes());if overlay {storage.set_word(0x1dc,color(states[slot as usize],false,false));}let p=Panel {name:panel.name.clone(),path:panel.path.clone(),storage};let (node,material)=crate::native_hud_panels::payload(&p,dimensions,viewport.scalar,dpi,texture)?;let layer=p.storage.word(0x1a4);
  let record=serde_json::json!({"name":p.name,"slot":slot,"path":p.path,"asset":asset,"state":states[slot as usize],"color":p.storage.word(0x1dc),"mode":material.parameters.mode.x,"layer":layer,"uv":material.parameters.uv.to_array(),"node":format!("{:?},{:?},{:?},{:?}",node.left,node.top,node.width,node.height)});payloads.push((node,material,record,80+layer as i32));
 }Ok(payloads)})();let payloads=match result {Ok(v)=>v,Err(e)=>{clear(&mut live,&mut commands,&mut materials);eprintln!("Native QWER HUD render unavailable: {e}");return;}};
 clear(&mut live,&mut commands,&mut materials);let mut records=Vec::new();for (node,material,record,z) in payloads {records.push(record);let h=materials.add(material);live.entities.push(commands.spawn((node,MaterialNode(h.clone()),GlobalZIndex(z),Name::new("NativeMap10HudSpell"))).id());live.materials.push(h);}live.signature=Some(signature);live.error=None;
 if let Ok(path)=std::env::var("OPENLEAGUE_NATIVE_HUD_SPELLS_TRACE") {let report=serde_json::json!({"complete":false,"champion":player.champion,"player":connection.id,"session":snapshot.session,"loaded_primary_icons":live.icons.len(),"loaded_summoner_icons":live.summoners.len(),"summoners":crate::native_hud_summoners::trace(player,snapshot.tick),"entities":live.entities.len(),"states":states,"elements":records,"limits":["Primary icons only; original texture lookup, dynamic spell variants/recasts/forms and whole framebuffer identity remain unqualified. Missing/ambiguous textures are omitted, never substituted.","Native state ordering and palette selector qualified. Actor availability/masks, cost modifiers, toggle/recast readiness and control special cases remain partial; current authoritative rank/cooldown/health/stun and native base mana cost used.","D/F use current core loadout/ready_at/disabled-cast flags. Summoner cooldown totals use current unmodified core rules, Smite90 provisional and Heal240. Tooltip/hover/flash, upgraded summoners and original framebuffer equivalence remain open."]});if let Err(e)=std::fs::write(path,serde_json::to_vec_pretty(&report).unwrap()) {eprintln!("Native QWER HUD trace failed: {e}");}}
}
fn signature(session:u64,id:Option<u32>,player:&openleague_core::Champion,states:&[u32;6],dimensions:[u32;2],dpi:f32,scalar:f32)->String {
 format!("{session}:{id:?}:{}:{:?}:{:?}:{states:?}:{dimensions:?}:{dpi}:{}",player.champion,player.summoners.spells,player.summoners.ready_at,scalar.to_bits())
}
#[cfg(test)] mod tests {
 use super::*;
 #[test] fn every_executed_native_state_and_palette_case_matches() {let c:serde_json::Value=serde_json::from_str(include_str!("../../../data/4.20/native_hud_spell_states_contract.json")).unwrap();assert_eq!(c["state_case_count"],384);assert_eq!(c["color_case_count"],192);for a in c["state_cases"].as_array().unwrap() {assert_eq!(state(a["available"].as_bool().unwrap(),a["cooldown"].as_f64().unwrap() as f32,a["rank"].as_u64().unwrap() as u8,a["allowed"].as_bool().unwrap(),a["resource_state"].as_u64().unwrap() as u32),a["state"].as_u64().unwrap() as u32);}for a in c["color_cases"].as_array().unwrap() {assert_eq!(color(a["state"].as_u64().unwrap() as u32,a["override"].as_bool().unwrap(),a["hover"].as_bool().unwrap()),a["color"].as_u64().unwrap() as u32);}}
 #[test] fn all486_source_primary_icon_payloads_and_fourteen_widgets_are_preserved() {let root=std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");let mut provider=crate::native_zip_provider::Provider::from_catalog(&root).unwrap();let hud=provider.startup_hud(&root).unwrap();let panels=source(&hud).unwrap();assert_eq!(panels.len(),14);let manifest:serde_json::Value=serde_json::from_str(include_str!("../../../data/4.20/native_spell_icons.json")).unwrap();let entries:Vec<_>=manifest["entries"].as_array().unwrap().iter().filter(|e|e["field"]=="InventoryIcon").collect();assert_eq!(entries.len(),486);for entry in entries {let bytes=std::fs::read(root.join("assets").join(entry["asset"].as_str().unwrap())).unwrap();let image=crate::native_hud_atlases::decode(&bytes,CompressedImageFormats::BC).unwrap();assert_eq!(image.data.as_deref(),Some(&bytes[128..]));assert_eq!(image.texture_descriptor.size.width,entry["width"].as_u64().unwrap() as u32);}for panel in panels {let (_,material)=crate::native_hud_panels::payload(&panel,[1280,800],1.0,1.0,Handle::default()).unwrap();assert_eq!(material.parameters.mode.x,if panel.name.contains("Overlay") || panel.name.contains("HotKeyBG") {0.0}else {1.0});}}
 #[test] fn authoritative_annie_learning_cast_and_cooldown_change_hud_state() {let root=std::path::PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../..");let nav=openleague_core::Navigation::load(&std::fs::read_to_string(root.join("assets/maps/tt_navigation_grid.json")).unwrap(),&std::fs::read(root.join("assets/maps/tt_navigation_grid.cells.bin")).unwrap()).unwrap();let mut sim=openleague_core::Simulation::new(nav).unwrap();let id=sim.join("annie").unwrap();assert_eq!(player_states(&sim.players[&id],sim.tick).unwrap(),[2;4]);sim.command(id,openleague_core::Action::Learn {slot:2}).unwrap();assert_eq!(player_states(&sim.players[&id],sim.tick).unwrap(),[2,2,0,2]);sim.command(id,openleague_core::Action::Cast {slot:2,target:None}).unwrap();assert_eq!(player_states(&sim.players[&id],sim.tick).unwrap(),[2,2,4,2]);let until=sim.players[&id].cooldowns[2];while sim.tick<until {sim.advance();}assert_eq!(player_states(&sim.players[&id],sim.tick).unwrap(),[2,2,0,2]);let mut p=sim.players[&id].clone();p.mana=0.0;assert_eq!(player_states(&p,sim.tick).unwrap(),[2,2,5,2]);p.health=0.0;assert_eq!(player_states(&p,sim.tick).unwrap(),[2,2,3,2]);}
}

#[cfg(test)] mod summoner_signature_tests {
 #[test] fn session_and_loadout_changes_invalidate_icons_even_when_state_is_ready() {
  let nav=openleague_core::Navigation::load(include_str!("../../../assets/maps/tt_navigation_grid.json"),include_bytes!("../../../assets/maps/tt_navigation_grid.cells.bin")).unwrap();let mut sim=openleague_core::Simulation::new(nav).unwrap();let id=sim.join_with_summoners("garen",[Some(openleague_core::summoners::Spell::Barrier),None]).unwrap();let mut p=sim.players[&id].clone();
  let a=super::signature(1,Some(id),&p,&[0;6],[1280,800],1.,1.);p.summoners.spells[0]=Some(openleague_core::summoners::Spell::Smite);let b=super::signature(1,Some(id),&p,&[0;6],[1280,800],1.,1.);assert_ne!(a,b);assert_ne!(b,super::signature(2,Some(id),&p,&[0;6],[1280,800],1.,1.));p.summoners.ready_at[0]=2700;assert_ne!(b,super::signature(1,Some(id),&p,&[0;6],[1280,800],1.,1.));
 }
}
